lines, chapters = [], []
for cid, title, ls in CH:
    ids = []
    for i, (v, t) in enumerate(ls, 1):
        lid = f"{cid}_{i:02d}"
        ln = {"id": lid, "text": t}
        if v == S:
            ln["voice"] = S
        lines.append(ln); ids.append(lid)
    chapters.append({"id": cid, "title": title, "lines": ids})

job = {"voice": D, "rate": "+4%", "pitch": "+0Hz", "lines": lines}
(HERE.parents[1] / "jobs/tts/news_week44.json").write_text(json.dumps(job, ensure_ascii=False, indent=1))
(HERE / "chapters.json").write_text(json.dumps(chapters, ensure_ascii=False, indent=1))
n = sum(len(l["text"]) for l in lines)
print("lines", len(lines), "chars", n, "≈ min", round(n / 780, 1))
